module pharmacy(\n    input clk,\n    input rst_n,\n    input start,\n    input load_enable,\n    input [31:0] load_drop_time,\n    input load_type,\n    input [8:0] load_fill_time,\n    input load_done,\n    output reg [63:0] sum_S,\n    output reg [63:0] sum_R,\n    output reg [31:0] count_S,\n    output reg [31:0] count_R,\n    output reg done\n);\n    \n    parameter N = 16;\n    parameter T = 4;\n    \n    reg [31:0] drop_time [0:N-1];\n    reg type_reg [0:N-1];\n    reg [8:0] fill_time [0:N-1];\n    reg [4:0] load_count;\n    \n    localparam [2:0] IDLE = 3'b000;\n    localparam [2:0] LOAD = 3'b001;\n    localparam [2:0] SORT = 3'b010;\n    localparam [2:0] SCHEDULE = 3'b011;\n    localparam [2:0] DONE_STATE = 3'b100;\n    reg [2:0] state, next_state;\n    \n    reg [4:0] sort_pass;\n    reg [4:0] sort_index;\n    reg sort_swapped;\n    \n    reg [4:0] sched_index;\n    reg [31:0] tech_free_time [0:T-1];\n    reg [31:0] min_free_time;\n    reg [1:0] min_tech;\n    \n    integer i;\n    reg [31:0] completion_time;\n    reg [31:0] delay;\n    reg [31:0] min_temp;\n    reg [1:0] tech_temp;\n    \n    // State transition\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) state <= IDLE;\n        else state <= next_state;\n    end\n    \n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: if (start) next_state = LOAD;\n            LOAD: if (load_done && load_count < N) next_state = SORT;\n            SORT: begin\n                if (sort_pass >= load_count - 1 || sort_swapped == 1'b0)\n                    next_state = SCHEDULE;\n            end\n            SCHEDULE: if (sched_index >= load_count) next_state = DONE_STATE;\n            DONE_STATE: next_state = IDLE;\n            default: next_state = IDLE;\n        endcase\n    end\n    \n    // Load logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            for (i = 0; i < N; i = i + 1) begin\n                drop_time[i] <= 32'd0;\n                type_reg[i] <= 1'b0;\n                fill_time[i] <= 9'd0;\n            end\n            load_count <= 5'd0;\n        end\n        else if (state == LOAD) begin\n            if (load_enable && (load_count < N)) begin\n                drop_time[load_count] <= load_drop_time;\n                type_reg[load_count] <= load_type;\n                fill_time[load_count] <= load_fill_time;\n                load_count <= load_count + 5'd1;\n            end\n        end\n        else if (state == IDLE) begin\n            load_count <= 5'd0;\n        end\n    end\n    \n    // Bubble sort\n    function automatic reg should_swap(input [4:0] i, input [4:0] j);\n        begin\n            if (drop_time[i] != drop_time[j])\n                should_swap = (drop_time[i] > drop_time[j]);\n            else if (type_reg[i] != type_reg[j])\n                should_swap = (type_reg[i] < type_reg[j]);\n            else\n                should_swap = (fill_time[i] > fill_time[j]);\n        end\n    endfunction\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            sort_pass <= 5'd0;\n            sort_index <= 5'd0;\n            sort_swapped <= 1'b0;\n        end\n        else if (state == SORT) begin\n            if (sort_pass < load_count) begin\n                if (sort_index < (load_count - 5'd1 - sort_pass)) begin\n                    if (should_swap(sort_index, sort_index + 5'd1)) begin\n                        // Perform swap\n                        drop_time[sort_index] <= drop_time[sort_index + 5'd1];\n                        drop_time[sort_index + 5'd1] <= drop_time[sort_index];\n                        type_reg[sort_index] <= type_reg[sort_index + 5'd1];\n                        type_reg[sort_index + 5'd1] <= type_reg[sort_index];\n                        fill_time[sort_index] <= fill_time[sort_index + 5'd1];\n                        fill_time[sort_index + 5'd1] <= fill_time[sort_index];\n                        sort_swapped <= 1'b1;\n                    end\n                    sort_index <= sort_index + 5'd1;\n                end\n                else begin\n                    sort_index <= 5'd0;\n                    if (sort_swapped) sort_pass <= sort_pass + 5'd1;\n                    else sort_pass <= load_count;\n                    sort_swapped <= 1'b0;\n                end\n            end\n        end\n        else begin\n            sort_pass <= 5'd0;\n            sort_index <= 5'd0;\n            sort_swapped <= 1'b0;\n        end\n    end\n    \n    // Tech min calculation\n    always @(*) begin\n        min_free_time = tech_free_time[0];\n        min_tech = 2'd0;\n        for (i = 1; i < T; i = i + 1) begin\n            if (tech_free_time[i] < min_free_time) begin\n                min_free_time = tech_free_time[i];\n                min_tech = i[1:0];\n            end\n        end\n    end\n    \n    // Scheduling logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            sched_index <= 5'd0;\n            for (i = 0; i < T; i = i + 1) begin\n                tech_free_time[i] <= 32'd0;\n            end\n            sum_S <= 64'd0;\n            sum_R <= 64'd0;\n            count_S <= 32'd0;\n            count_R <= 32'd0;\n        end\n        else if (state == SCHEDULE) begin\n            if (sched_index < load_count) begin\n                if (drop_time[sched_index] > min_free_time) begin\n                    completion_time = drop_time[sched_index] + fill_time[sched_index];\n                    delay = fill_time[sched_index];\n                end\n                else begin\n                    completion_time = min_free_time + fill_time[sched_index];\n                    delay = min_free_time - drop_time[sched_index] + fill_time[sched_index];\n                end\n                \n                tech_free_time[min_tech] <= completion_time;\n                \n                if (type_reg[sched_index] == 1'b1) begin\n                    sum_S <= sum_S + delay;\n                    count_S <= count_S + 32'd1;\n                end\n                else begin\n                    sum_R <= sum_R + delay;\n                    count_R <= count_R + 32'd1;\n                end\n                \n                sched_index <= sched_index + 5'd1;\n            end\n        end\n        else begin\n            sched_index <= 5'd0;\n        end\n    end\n    \n    // Done signal\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) done <= 1'b0;\n        else begin\n            if (state == DONE_STATE) done <= 1'b1;\n            else done <= 1'b0;\n        end\n    end\n    \nendmodule